+// API keys, roles and the audit log. Keys live in `apiKeys` as
+// { key, name, role }; every request that changes data leaves an entry in
+// `audit` (docs/DATA.md).
+import { createHash, timingSafeEqual } from "node:crypto";
+
+// What each role may do. `read` is every GET; `kitchen` is cooking, waste,
+// temperature logs and stock-take counts; `manage` is every other change;
+// `audit` is reading the audit log.
+const ROLES = Object.freeze({
+  viewer: ["read"],
+  cook: ["read", "kitchen"],
+  manager: ["read", "kitchen", "manage", "audit"],
+});
+
+const digest = (s) => createHash("sha256").update(String(s)).digest();
+
+/** The API key record for `key`, or null when it is not known. */
+export function findKey(store, key) {
+  if (typeof key !== "string" || key === "") return null;
+  const wanted = digest(key);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) if (timingSafeEqual(digest(k.key), wanted)) found ??= k;
+  return found;
+}
+
+/** Whether `role` may perform `action` (read, kitchen, manage, audit). */
+export function allowed(role, action) {
+  return Object.hasOwn(ROLES, role) && ROLES[role].includes(action);
+}
+
+/** Appends an audit entry { id, at, key, method, path, status }; returns it. */
+export function recordAudit(store, { key, method, path, status }, { at }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, key, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => b.id - a.id);
+}
