+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, as, NOW } from "./helpers.js";
+
+test("no key or an unknown key is 401", async () => {
+  const { handle } = app();
+  const none = await handle({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const bad = await handle({ headers: { authorization: "Bearer nope" }, path: "/items" });
+  assert.equal(bad.status, 401);
+  const basic = await handle({ headers: { Authorization: "Basic manager-key-0001" }, path: "/items" });
+  assert.equal(basic.status, 401);
+});
+
+test("viewers only read", async () => {
+  const { handle, store } = app();
+  assert.equal((await handle({ headers: as("viewer"), path: "/items" })).status, 200);
+  const before = JSON.stringify(store.data.batches);
+  const res = await handle({ headers: as("viewer"), method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(res.status, 403);
+  assert.equal(res.body.error.code, "forbidden");
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("cooks cook, waste, log temperatures and count, but nothing else", async () => {
+  const { handle } = app();
+  const cook = as("cook");
+  assert.equal((await handle({ headers: cook, method: "POST", path: "/recipes/1/cook", body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ headers: cook, method: "POST", path: "/batches/6/waste", body: { qty: 0.5 } })).status, 201);
+  assert.equal((await handle({ headers: cook, method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await handle({ headers: cook, method: "POST", path: "/stocktakes", body: { location: "dry" } })).status, 403);
+  const take = (await handle({ headers: as("manager"), method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await handle({ headers: cook, method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 6, counted: 12 } })).status, 200);
+  assert.equal((await handle({ headers: cook, method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 403);
+  assert.equal((await handle({ headers: cook, method: "POST", path: "/jobs/nightly" })).status, 403);
+  assert.equal((await handle({ headers: cook, path: "/audit" })).status, 403);
