+  const { handle } = app();
+  await handle({ headers: as("cook"), method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  await handle({ headers: as("viewer"), method: "POST", path: "/jobs/nightly" });
+  await handle({ headers: as("viewer"), path: "/items" });
+  await handle({ method: "POST", path: "/jobs/nightly" });
+  assert.equal((await handle({ headers: as("viewer"), path: "/audit" })).status, 403);
+  const res = await handle({ headers: as("manager"), path: "/audit" });
+  assert.equal(res.status, 200);
+  const at = new Date(NOW).toISOString();
+  assert.deepEqual(res.body.map(({ id, ...e }) => e), [
+    { at, key: "front desk", method: "POST", path: "/jobs/nightly", status: 403 },
+    { at, key: "line cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+  ]);
+});
